package com.joysistvi.CyberAccess.controller;
import com.joysistvi.CyberAccess.model.Food; import com.joysistvi.CyberAccess.service.FoodServiceImpl; import java.sql.SQLException; import java.util.List;
public class FoodController {private final FoodServiceImpl service;public FoodController(){this(new FoodServiceImpl());}public FoodController(FoodServiceImpl s){service=s;}public List<Food> getAll()throws SQLException{return service.getAll();}public List<Food> getByCategory(int id)throws SQLException{return service.getByCategory(id);}public Food getById(int id)throws SQLException{return service.getById(id);}public void add(Food x)throws SQLException{service.add(x);}public boolean update(Food x)throws SQLException{return service.update(x);}public boolean delete(int id)throws SQLException{return service.delete(id);}}
